import{_ as i,o as a,c as t,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const g=JSON.parse('{"title":"Yoga scoring identity and display compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0004-yoga-scoring-identity.md","filePath":"decisions/0004-yoga-scoring-identity.md","lastUpdated":1789990776000}'),o={name:"decisions/0004-yoga-scoring-identity.md"};function s(r,e,d,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="yoga-scoring-identity-and-display-compatibility" tabindex="-1">Yoga scoring identity and display compatibility <a class="header-anchor" href="#yoga-scoring-identity-and-display-compatibility" aria-label="Permalink to &quot;Yoga scoring identity and display compatibility&quot;">​</a></h1><p>Date: 2026-09-19. Scope: issue #183.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The scoring boundary uses Python&#39;s canonical identity for all 27 Yoga indices. The browser&#39;s existing Priti, Shula and Variyana display/input aliases remain valid. They map respectively to Preeti, Shoola and Variyan before policy lookup.</p><p>This explicitly chooses semantic identity after canonicalization instead of renaming the raw browser facts; #183&#39;s original exact raw-name criterion is replaced by exact canonical-name/index parity at the policy boundary. Existing raw-name assertions and display contracts remain unchanged.</p><p>The existing generated schema1 artifact gains an additive <code>canonicalYogaNames</code> array from <code>panchangam_names.YOGA_NAMES</code>; its ordered <code>browserYogaNames</code> array is unchanged. The exporter owns both projections and its drift guard remains in the full Python gate. Removing or reordering indices would require a separate incompatible-contract decision.</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><p>Preeti/Priti receives the existing auspicious +1 policy. Shoola/Shula receives the existing -1 policy through the inclusive 120-minute partial-dosha boundary; the next minute is neutral. Canonical and alias feed names identify the same Yoga start. A genuinely different current feed Yoga uses its end as the next Yoga start. Explicit activity exclusions accept either spelling. Variyan/Variyana remains neutral. Reasons retain the input display spelling; calendar labels and arithmetic do not change.</p><p>The shared all-27 fixture is checked against Python&#39;s existing slot scorer and against both browser spellings. It is regression/parity evidence, not a new independent validation of the traditional disposition rules or slot astronomy. The selected-system approximation issue #182 remains separate.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><p>No engine, ICS, MCP, persisted profile or existing assertion changes. No new Yoga interpretation, score weight, partial-window duration or rule. Only previously missed alias lookups change their score/exclusion outcome.</p>',11)])])}const y=i(o,[["render",s]]);export{g as __pageData,y as default};
